// [FIX-图片缓存] 主界面图片内存缓存系统
// 用户反馈退一次图片就掉一次，原因是base64 URL在DOM中被频繁重设
// 使用内存缓存避免重复加载，同时预加载关键图片防止闪烁
window._desktopImageCache = {};
window._cacheDesktopImage = function(key, url) {
    if (!url || url === 'none') return;
    // 已在缓存中且URL没变，跳过
    if (window._desktopImageCache[key] && window._desktopImageCache[key].url === url) return;
    // 创建Image对象预加载并缓存
    var img = new Image();
    img.onload = function() {
        window._desktopImageCache[key] = { url: url, loaded: true, img: img, ts: Date.now() };
    };
    img.onerror = function() {
        // 加载失败也记录，避免反复重试
        window._desktopImageCache[key] = { url: url, loaded: false, ts: Date.now() };
    };
    // data: URL不需要跨域设置
    if (!url.startsWith('data:')) {
        img.crossOrigin = 'anonymous';
    }
    img.src = url;
    // 即使还没加载完也先记录URL，防止重复触发加载
    window._desktopImageCache[key] = { url: url, loaded: false, img: img, ts: Date.now() };
};

// [FIX-图片缓存] 检查图片URL是否已缓存且加载成功
window._isImageCached = function(key, url) {
    var c = window._desktopImageCache[key];
    return c && c.url === url && c.loaded;
};

// Clear long press state
window._clearLongPressState = function() {
    if (typeof isLongPress !== 'undefined') isLongPress = false;
    if (typeof longPressTimer !== 'undefined' && longPressTimer) {
        clearTimeout(longPressTimer);
        longPressTimer = null;
    }
};

