                    const momentsHist = store.moments.filter(m=>m.name===c.name).slice(0,3).map(m=>m.content || '').join('; ');
                    
                    // 获取最近的日记标题和摘要，避免生成重复内容
                    const prevDiaries = (store.diaries[contactId] || []).slice(-8);
