                         const _realHour = _now.getHours();
                         const _realTimePeriod = _realHour < 6 ? '凌晨' : _realHour < 9 ? '早晨' : _realHour < 12 ? '上午' : _realHour < 14 ? '中午' : _realHour < 18 ? '下午' : _realHour < 22 ? '晚上' : '深夜';
                         // 统一时间：虚拟时间开启时，所有时间相关行为都基于虚拟时间
                         const _displayDate = _useVirtualDate ? p.dateVal : _realDate;
                         const _displayTime = _useVirtualTime ? p.timeVal : _realTime;
                         const _displayHour = _useVirtualTime ? parseInt(p.timeVal.split(':')[0]) || _realHour : _realHour;
                         const _displayTimePeriod = _displayHour < 6 ? '凌晨' : _displayHour < 9 ? '早晨' : _displayHour < 12 ? '上午' : _displayHour < 14 ? '中午' : _displayHour < 18 ? '下午' : _displayHour < 22 ? '晚上' : '深夜';
                         const _percHour = _displayHour;
                         const _timePeriod = _displayTimePeriod;
                         
                         // Global Custom Weather override
                         let globalWeather = (p.customWeather && p.weatherVal) ? p.weatherVal : null;
                         
                         // Locations
                         // User
                         let userVC = c.settings?.userVirtualCity || (p.customCity ? p.cityVal : p.city);
                         let userRC = c.settings?.userRealCity || (p.customCity ? p.realCityVal : p.city);
                         if(!userVC) userVC = "未知";
                         if(!userRC) userRC = userVC;

                         // Contact location
                         let aiVC = c.settings?.aiVirtualCity; // If empty, implies same as user
                         let aiRC = c.settings?.aiRealCity;
                         let isSameLoc = !aiVC;
                         if(isSameLoc) { aiVC = userVC; aiRC = userRC; }
                         else { if(!aiRC) aiRC = aiVC; }

                         // Calendar/Holiday context
                         let calendarContext = '';
                         if (typeof getEventsForDate === 'function') {
                             const todayStr = _useVirtualDate ? p.dateVal : new Date().toISOString().split('T')[0];
                             const events = getEventsForDate(todayStr);
                             const holidayNames = (events.holidays || []).map(h => `${h.icon}${h.name}`);
                             const specialNames = (events.specials || []).map(s => `${s.icon || '📌'}${s.name}`);
                             const allEvents = [...holidayNames, ...specialNames];
                             if (allEvents.length > 0) {
                                 calendarContext = `\n                        [Today's Events/Holidays: ${allEvents.join(', ')}]`;
                             }
                         }

                         // 计算用户上次消息距今多久
                         // 当虚拟时间开启时，跳过idle计算（虚拟时间是静态的，不存在"多久没回复"）
